  if(!enabled||!buffers||!context||context.state!=='running'||document.hidden)return;
  if(kind==='hover'&&voices.some(v=>v.kind==='escritura'))return;
  const id=kind==='escritura'?(samples[sample]?sample:'pencil-1'):kind==='hover'?'hover':kind==='confirmacion'?'positive':kind==='atencion'?'negative':'click';
