  class Reporte {
    constructor(root) {
      this.root=root; this.parts=[]; this.restore=[]; this.abort=new AbortController(); this.dead=false;
      try {
        switch(root.dataset.reporte) {
          case 'cascada': this.waterfall(); break;
          case 'multiples': this.multiples(); break;
